#include "reuse_primitives.c"
static int gone(mach_port_t p){mach_port_type_t t=0;return mach_port_type(mach_task_self(),p,&t)==KERN_INVALID_NAME;}
static int ack_at(mach_port_t inbox,pid_t peer,unsigned stage){union receive m;return !receive_message(&m,inbox) && peer_matches(&m,peer) && m.ack.h.msgh_size==sizeof(struct ack) && m.ack.magic==MAGIC && m.ack.stage==stage && m.ack.value==1;}
static int capture(IOSurfaceRef s,const char *folder,const char *name){uint8_t raw[LIMIT];return IOSurfaceGetAllocSize(s)==16384 && snapshot(s,raw,16384) && write_bytes(folder,name,raw,16384);}
static int observe(IOSurfaceRef alias,unsigned stage,const char *folder,FILE *file){
 uint8_t bytes[LIMIT];uint32_t before=IOSurfaceGetSeed(alias),locked=0,unlocked=0;kern_return_t l=IOSurfaceLock(alias,kIOSurfaceLockReadOnly,&locked);if(l)return 0;memcpy(bytes,IOSurfaceGetBaseAddress(alias),16384);kern_return_t u=IOSurfaceUnlock(alias,kIOSurfaceLockReadOnly,&unlocked);if(u)return 0;char name[64];snprintf(name,sizeof(name),"peer-stage-%u.bin",stage);if(!write_bytes(folder,name,bytes,16384))return 0;
 fprintf(file,"%s{\"stage\":%u,\"before\":%u,\"lock_seed\":%u,\"unlock_seed\":%u,\"after\":%u,\"lock_code\":%d,\"unlock_code\":%d}",stage?",":"",stage,before,locked,unlocked,IOSurfaceGetSeed(alias),l,u);return !fflush(file);
}
static int peer(const char *service,pid_t parent,const char *folder){
 IOSurfaceRef alias=NULL;mach_port_t remote=MACH_PORT_NULL,inbox=MACH_PORT_NULL,resource=MACH_PORT_NULL;FILE *file=NULL;int result=4;
 if(bootstrap_look_up(bootstrap_port,service,&remote) || mach_port_allocate(mach_task_self(),MACH_PORT_RIGHT_RECEIVE,&inbox))goto done;
 struct ack ready={0};ready.h.msgh_bits=MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND,MACH_MSG_TYPE_MAKE_SEND);ready.h.msgh_size=sizeof(ready);ready.h.msgh_remote_port=remote;ready.h.msgh_local_port=inbox;ready.magic=MAGIC;
 if(mach_msg(&ready.h,MACH_SEND_MSG|MACH_SEND_TIMEOUT,sizeof(ready),0,MACH_PORT_NULL,3000,MACH_PORT_NULL) || !receive_surface(inbox,parent,1,&alias,&resource) || !send_refs(resource,1))goto done;
 if(IOSurfaceGetWidth(alias)!=17 || IOSurfaceGetHeight(alias)!=9 || IOSurfaceGetBytesPerRow(alias)!=128 || IOSurfaceGetAllocSize(alias)!=16384)goto done;mach_port_t old=resource;if(mach_port_deallocate(mach_task_self(),resource) || !gone(old))goto done;resource=MACH_PORT_NULL;
 char path[4096];snprintf(path,sizeof(path),"%s/peer.json",folder);file=fopen(path,"w");if(!file)goto done;fprintf(file,"{\"pid\":%d,\"parent\":%d,\"surface_id\":%u,\"audit_peer_verified\":true,\"imported_right_released\":true,\"local_resource_name_removed\":true,\"observations\":[",getpid(),parent,IOSurfaceGetID(alias));
 if(!observe(alias,0,folder,file) || send_ack(remote,1,1))goto done;unsigned requests[4]={6,7,9,11},replies[4]={5,8,10,12};
 for(unsigned i=0;i<4;i++)if(!ack_at(inbox,parent,requests[i]) || !observe(alias,i+1,folder,file) || send_ack(remote,replies[i],1))goto done;
 if(!ack_at(inbox,parent,13))goto done;CFRelease(alias);alias=NULL;fprintf(file,"],\"cf_alias_released\":true}\n");if(fclose(file))goto done;file=NULL;if(send_ack(remote,14,1))goto done;result=0;
 done:if(file)fclose(file);if(alias)CFRelease(alias);if(MACH_PORT_VALID(resource))mach_port_deallocate(mach_task_self(),resource);if(MACH_PORT_VALID(remote))mach_port_deallocate(mach_task_self(),remote);if(MACH_PORT_VALID(inbox))mach_port_mod_refs(mach_task_self(),inbox,MACH_PORT_RIGHT_RECEIVE,-1);return result;
}
static int one(const char *binary,const char *folder){
 IOSurfaceRef original=NULL,lookup=NULL;mach_port_t inbox=MACH_PORT_NULL,remote=MACH_PORT_NULL,resource=MACH_PORT_NULL;pid_t child=-1;int registered=0,waited=0,status=0,result=3,write_locked=0;uint32_t locked=0,unlocked=0,restored_lock=0,restored_unlock=0;char service[128],pidtext[32],hex[33];unsigned char nonce[16];arc4random_buf(nonce,sizeof(nonce));for(unsigned i=0;i<16;i++)sprintf(hex+i*2,"%02x",nonce[i]);snprintf(service,sizeof(service),"local.re.surface.%d.%s",getpid(),hex);snprintf(pidtext,sizeof(pidtext),"%d",getpid());
 if(mach_port_allocate(mach_task_self(),MACH_PORT_RIGHT_RECEIVE,&inbox) || mach_port_insert_right(mach_task_self(),inbox,inbox,MACH_MSG_TYPE_MAKE_SEND) || bootstrap_register(bootstrap_port,service,inbox))goto done;registered=1;
 original=create_surface(17,9,49,NULL);if(!original || !capture(original,folder,"parent-initial.bin"))goto done;uint32_t id=IOSurfaceGetID(original),initial=IOSurfaceGetSeed(original);resource=IOSurfaceCreateMachPort(original);if(!MACH_PORT_VALID(resource) || !send_refs(resource,1))goto done;
 child=fork();if(child==0){execl(binary,binary,"--seed-peer",service,pidtext,folder,NULL);_exit(127);}if(child<0)goto done;union receive ready;if(receive_message(&ready,inbox) || !peer_matches(&ready,child) || ready.ack.magic!=MAGIC || ready.ack.stage!=0)goto done;remote=ready.ack.h.msgh_remote_port;
 if(!transfer_surface(remote,resource,original,49,1) || !ack_at(inbox,child,1))goto done;mach_port_t old=resource;if(mach_port_deallocate(mach_task_self(),resource) || !gone(old))goto done;resource=MACH_PORT_NULL;
 if(IOSurfaceLock(original,0,&locked))goto done;write_locked=1;uint8_t *bytes=IOSurfaceGetBaseAddress(original);if(!write_bytes(folder,"parent-locked-before.bin",bytes,16384) || send_ack(remote,6,1) || !ack_at(inbox,child,5))goto done;
 bytes[0]^=1;bytes[68]^=1;bytes[16383]^=1;if(!write_bytes(folder,"parent-locked-after.bin",bytes,16384) || send_ack(remote,7,1) || !ack_at(inbox,child,8))goto done;
 if(IOSurfaceUnlock(original,0,&unlocked))goto done;write_locked=0;if(!capture(original,folder,"parent-after-unlock.bin") || send_ack(remote,9,1) || !ack_at(inbox,child,10))goto done;
 if(IOSurfaceLock(original,0,&restored_lock))goto done;write_locked=1;bytes=IOSurfaceGetBaseAddress(original);bytes[0]^=1;bytes[68]^=1;bytes[16383]^=1;if(IOSurfaceUnlock(original,0,&restored_unlock))goto done;write_locked=0;
 if(!capture(original,folder,"parent-restored.bin") || send_ack(remote,11,1) || !ack_at(inbox,child,12) || send_ack(remote,13,1) || !ack_at(inbox,child,14))goto done;
 if(waitpid(child,&status,0)!=child)goto done;waited=1;if(!WIFEXITED(status) || WEXITSTATUS(status)!=0)goto done;CFRelease(original);original=NULL;usleep(100000);lookup=IOSurfaceLookup(id);int present=lookup!=NULL;if(lookup){CFRelease(lookup);lookup=NULL;}
 if(!remove_rendezvous(&inbox,service))goto done;registered=0;old=remote;if(mach_port_deallocate(mach_task_self(),remote) || !gone(old))goto done;remote=MACH_PORT_NULL;
 printf("{\"sender_pid\":%d,\"receiver_pid\":%d,\"surface_id\":%u,\"initial_seed\":%u,\"lock_seed\":%u,\"unlock_seed\":%u,\"restore_lock_seed\":%u,\"restore_unlock_seed\":%u,\"allocation_bytes\":16384,\"stride\":128,\"resource_names_removed\":true,\"parent_cf_released\":true,\"peer_exit\":0,\"peer_signal\":0,\"rendezvous_removed\":true,\"peer_endpoint_name_removed\":true,\"lookup_after_release\":%s}\n",getpid(),child,id,initial,locked,unlocked,restored_lock,restored_unlock,present?"true":"false");result=0;
 done:if(write_locked&&original)IOSurfaceUnlock(original,0,NULL);if(child>0&&!waited){kill(child,SIGKILL);waitpid(child,NULL,0);}if(lookup)CFRelease(lookup);if(original)CFRelease(original);if(MACH_PORT_VALID(resource))mach_port_deallocate(mach_task_self(),resource);if(registered)remove_rendezvous(&inbox,service);if(MACH_PORT_VALID(remote))mach_port_deallocate(mach_task_self(),remote);if(MACH_PORT_VALID(inbox))mach_port_mod_refs(mach_task_self(),inbox,MACH_PORT_RIGHT_RECEIVE,-1);return result;
}
int main(int argc,char **argv){alarm(12);if(argc==5&&!strcmp(argv[1],"--seed-peer")){char *end=NULL;long parent=strtol(argv[3],&end,10);if(!end||*end||parent<=1||getppid()!=parent)return 2;return peer(argv[2],(pid_t)parent,argv[4]);}if(argc!=2)return 2;for(unsigned i=0;i<2;i++){char folder[4096];snprintf(folder,sizeof(folder),"%s/repeat-%u",argv[1],i);int result=one(argv[0],folder);if(result)return result;}return 0;}
